/**
 * SEO contract tests for the Cloudflare Pages Functions.
 *
 * Run: node --test tests/functions
 *
 * The robots.txt and sitemap.xml expectations are copied verbatim from
 * backend/app/seo.py output (generated by the Python module itself), so the
 * frontend-only deploy keeps the same bytes crawlers already indexed.
 */
import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import { test } from "node:test";

import {
  isKnownPath,
  renderHead,
  robotsTxt,
  sitemapXml,
  statusFor,
  STATIC_PAGES,
} from "../../functions/lib/seo.ts";
import type { Bundle } from "../../functions/lib/seo.ts";

const ORIGIN = "https://setapak-dental-jb.localhost";

/** The shape of frontend/dist/index.html: stale data-rh tags and a stale title. */
const SHELL = `<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <meta data-rh="true" property="og:type" content="website" />
    <meta data-rh="true" property="og:site_name" content="Stale Site" />
    <meta
      data-rh="true"
      name="description"
      content="stale description"
    />
    <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
    <title>Stale title</title>
  </head>
  <body>
    <div id="root"></div>
  </body>
</html>
`;

const BUNDLE: Bundle = {
  tenant: { id: "11111111-1111-1111-1111-111111111111", slug: "setapak", status: "active" },
  site: {
    brand_name: { en: "Klinik Pergigian Setapak", zh: "Setapak 牙科诊所", ms: "Klinik Pergigian Setapak" },
    default_locale: "en",
    locales: ["en", "ms", "zh"],
  },
  content: {
    home: {
      seo: {
        description: {
          en: "General dental care in Taman Sri Tebrau, Johor Bahru.",
          zh: "新山大丰花园全科牙科诊所。",
        },
      },
      hero: {
        eyebrow: { en: "Taman Sri Tebrau · Johor Bahru", zh: "新山大丰花园 · Taman Sri Tebrau" },
        spec_line: { en: "4.8 ★ from 850+ Google reviews" },
      },
    },
  },
  offerings: [
    { slug: "evening-emergency-toothache-care" },
    { slug: "scaling-polishing-checkup" },
    { slug: "root-canal-crown-restoration" },
  ],
};

/** The demo bundle's values so the sitemap assertion matches the Python run. */
test("renderHead writes title, description, canonical and og:url", () => {
  const html = renderHead(SHELL, BUNDLE, ORIGIN, "/about");
  assert.ok(
    html.includes(
      "<title>Klinik Pergigian Setapak · Taman Sri Tebrau · Johor Bahru</title>",
    ),
    "title should be brand · hero eyebrow",
  );
  assert.ok(
    html.includes('name="description" content="General dental care in Taman Sri Tebrau, Johor Bahru."'),
    "meta description",
  );
  assert.ok(
    html.includes(`<link rel="canonical" href="${ORIGIN}/about" />`),
    "canonical URL",
  );
  assert.ok(html.includes(`property="og:url" content="${ORIGIN}/about"`), "og:url");
  assert.ok(html.includes('property="og:image" content="https://setapak-dental-jb.localhost/og.png"'));
  assert.ok(html.includes('property="og:image:width" content="1200"'));
  assert.ok(html.includes('property="og:image:height" content="630"'));
  assert.ok(html.includes('name="twitter:card" content="summary_large_image"'));
  assert.equal(html.match(/<title>/g)?.length, 1, "exactly one title tag");
});

test("the home page canonical is the origin with a single slash", () => {
  const html = renderHead(SHELL, BUNDLE, ORIGIN, "/");
  assert.ok(html.includes(`<link rel="canonical" href="${ORIGIN}/" />`));
  assert.ok(html.includes(`property="og:url" content="${ORIGIN}/"`));
});

test("renderHead removes the stale data-rh metas and title", () => {
  const html = renderHead(SHELL, BUNDLE, ORIGIN, "/");
  assert.ok(!html.includes("Stale title"), "old <title> should be gone");
  assert.ok(!html.includes("stale description"), "old description meta should be gone");
  assert.ok(!html.includes("Stale Site"), "old data-rh metas should be gone");
  assert.ok(html.includes('href="/favicon.svg"'), "non-SEO tags survive");
  // The rendered head owns exactly the 13 data-rh metas seo.py emits.
  assert.equal(html.match(/<meta\s+data-rh="true"/g)?.length, 13);
});

test("inline __SITE__ JSON cannot close its script tag", () => {
  const evil = '</script><script>alert(1)</script>\u2028\u2029';
  const html = renderHead(SHELL, { ...BUNDLE, evil }, ORIGIN, "/");
  assert.ok(!html.includes("</script><script>alert(1)"), "raw </script> leaked");
  const inline = html.match(
    /<script id="__SITE__" type="application\/json">([\s\S]*?)<\/script>/,
  );
  assert.ok(inline, "inline __SITE__ script is missing");
  assert.equal(inline[1].includes("<"), false, "every < is escaped as \\u003c");
  assert.equal(inline[1].includes("\u2028"), false, "U+2028 is escaped");
  assert.equal(inline[1].includes("\u2029"), false, "U+2029 is escaped");
  // The escaping is reversible: the client receives the bundle unchanged.
  assert.equal((JSON.parse(inline[1]) as { evil?: string }).evil, evil);
});

test("the description falls back to the hero spec_line", () => {
  const base: Bundle = {
    site: { brand_name: { en: "B" }, default_locale: "en" },
    content: { home: { hero: { spec_line: { en: "hero line" } } } },
    offerings: [],
  };
  assert.ok(renderHead(SHELL, base, "https://x.my", "/").includes('content="hero line"'));
  const withSeo: Bundle = {
    ...base,
    content: {
      home: {
        hero: { spec_line: { en: "hero line" } },
        seo: { description: { en: "Plain sentence for search results." } },
      },
    },
  };
  assert.ok(
    renderHead(SHELL, withSeo, "https://x.my", "/").includes(
      'content="Plain sentence for search results."',
    ),
  );
});

test("isKnownPath matches the SPA router and the Python rules", () => {
  for (const path of [
    "/",
    "/doctors",
    "/services",
    "/services/scaling-polishing-checkup",
    "/booking/AAA-0001",
    "/about/",
  ]) {
    assert.equal(isKnownPath(path, BUNDLE), true, path);
    assert.equal(statusFor(path, BUNDLE), 200, path);
  }
  for (const path of [
    "/nope",
    "/nope-123",
    "/services/nope",
    "/services/scaling-polishing-checkup/extra",
    "/about/extra",
    "/booking",
    // The backstage is its own app now, so these are not site pages.
    "/manage",
    "/manage/login",
  ]) {
    assert.equal(isKnownPath(path, BUNDLE), false, path);
    assert.equal(statusFor(path, BUNDLE), 404, path);
  }
});

test("STATIC_PAGES contains every public <Route> including /doctors", () => {
  assert.deepEqual(
    [...STATIC_PAGES].sort(),
    ["about", "book", "contact", "doctors", "faq", "privacy", "services", "terms"],
  );
});

test("robotsTxt matches the Python output exactly", () => {
  const expected =
    "User-agent: *\n" +
    "Allow: /\n" +
    "Disallow: /booking/\n" +
    "Disallow: /api/\n" +
    "Sitemap: https://setapak-dental-jb.localhost/sitemap.xml\n";
  assert.equal(robotsTxt(ORIGIN), expected);
});

test("sitemapXml matches the Python output exactly", () => {
  const loc = (path: string) => `  <url><loc>${ORIGIN}${path}</loc></url>\n`;
  const expected =
    '<?xml version="1.0" encoding="UTF-8"?>\n' +
    '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' +
    loc("/") +
    loc("/services") +
    loc("/about") +
    loc("/doctors") +
    loc("/faq") +
    loc("/contact") +
    loc("/book") +
    loc("/privacy") +
    loc("/terms") +
    loc("/services/evening-emergency-toothache-care") +
    loc("/services/scaling-polishing-checkup") +
    loc("/services/root-canal-crown-restoration") +
    "</urlset>\n";
  assert.equal(sitemapXml(ORIGIN, BUNDLE), expected);
});

test("zh default_locale sets html lang=zh-Hans and the zh_MY og:locale", () => {
  const zh: Bundle = { ...BUNDLE, site: { ...BUNDLE.site, default_locale: "zh" } };
  const html = renderHead(SHELL, zh, ORIGIN, "/");
  assert.ok(html.includes('<html lang="zh-Hans">'), "html lang");
  assert.ok(html.includes('property="og:locale" content="zh_MY"'), "og:locale");
  assert.ok(
    html.includes("<title>Setapak 牙科诊所 · 新山大丰花园 · Taman Sri Tebrau</title>"),
    "zh brand + eyebrow",
  );
  assert.ok(html.includes('name="description" content="新山大丰花园全科牙科诊所。"'));
});

test("malay default_locale sets lang=ms and ms_MY", () => {
  const ms: Bundle = { ...BUNDLE, site: { ...BUNDLE.site, default_locale: "ms" } };
  const html = renderHead(SHELL, ms, ORIGIN, "/");
  assert.ok(html.includes('<html lang="ms">'));
  assert.ok(html.includes('property="og:locale" content="ms_MY"'));
});

const DIST_SHELL = new URL("../../frontend/dist/index.html", import.meta.url);

test(
  "the real built shell gets a tenant head",
  { skip: !existsSync(DIST_SHELL) && "frontend/dist/index.html is not built" },
  () => {
    const shell = readFileSync(DIST_SHELL, "utf8");
    const html = renderHead(shell, BUNDLE, ORIGIN, "/doctors");
    assert.ok(html.includes('id="__SITE__"'), "bootstrap data");
    assert.ok(html.includes(`<link rel="canonical" href="${ORIGIN}/doctors" />`));
    assert.ok(html.includes('name="description"'));
    assert.equal(html.match(/data-rh="true"/g)?.length, 13);
    assert.ok(html.includes('<html lang="en">'));
  },
);
